import * as THREE from 'three';
import { HypercubeParametric } from '..';
import { Parameters } from '../Parameters/Parameters';

import { Brush, Evaluator, SUBTRACTION } from 'three-bvh-csg';

import { DIRECTION } from '../../../../../utils/const';

export class Wall {
	public hypercubeParametric: HypercubeParametric;

	public mesh: THREE.Mesh[] = [];

	public door: THREE.Mesh;

	public scale: number = 1;
	private params: Parameters;

	private wallThickness: number = 0.5;
	private geometry = new THREE.BoxGeometry(1, 1, 1);

	private doorInnerA: DoorInner;
	private doorInnerB: DoorInner;

	constructor(hypercubeParametric: HypercubeParametric) {
		this.hypercubeParametric = hypercubeParametric;
		this.params = this.hypercubeParametric.params;
		this.init();
	}
	public init(): void {
		this.populateFixedWall();

		const offset = this.params.thickness * 2 + this.params.epsilon;

		const singleDoorWidth = 8;
		const doorWidth = singleDoorWidth * 2;
		const doorHight = 20;

		const widthMin = 4;

		const material = this.hypercubeParametric.configurator.materials.wallMaterial;
		const geometry = new THREE.BoxGeometry(this.params.width - offset, this.params.height - offset, this.wallThickness);

		const geometryDoorOpening = new THREE.BoxGeometry(doorWidth, doorHight, this.wallThickness);
		geometryDoorOpening.translate(0, -(this.params.height - offset) * 0.5 + doorHight * 0.5, 0);

		const aa = new Brush(geometry, material);
		const bb = new Brush(geometryDoorOpening, material);

		const evaluator = new Evaluator();
		const resultBrush = evaluator.evaluate(aa, bb, SUBTRACTION);
		resultBrush.receiveShadow = resultBrush.castShadow = true;
		resultBrush.position.y = this.params.groundY + this.params.height * 0.5;
		resultBrush.position.z = this.params.length * 0.5 - this.params.thickness * 0.5;

		this.mesh.push(resultBrush);
		this.hypercubeParametric.configurator.sceneWrapper.scene.add(resultBrush);

		const doorA = new THREE.Mesh(this.geometry, material);
		doorA.name = 'sliding-a';
		doorA.scale.set(singleDoorWidth, doorHight, this.wallThickness * 0.2);
		doorA.position.x = -singleDoorWidth * 0.5;
		doorA.position.y = this.params.groundY + doorHight * 0.5 + this.params.thickness;
		doorA.position.z = this.params.length * 0.5 - this.params.thickness * 0.5;
		this.mesh.push(doorA);
		this.hypercubeParametric.configurator.sceneWrapper.scene.add(doorA);

		const doorB = new THREE.Mesh(this.geometry, material);
		doorB.name = 'sliding-b';
		doorB.scale.set(singleDoorWidth, doorHight, this.wallThickness * 0.2);
		doorB.position.x = singleDoorWidth * 0.5;
		doorB.position.y = this.params.groundY + doorHight * 0.5 + this.params.thickness;
		doorB.position.z = this.params.length * 0.5 - this.params.thickness * 0.5;
		this.mesh.push(doorB);
		this.hypercubeParametric.configurator.sceneWrapper.scene.add(doorB);

		this.doorInnerA = new DoorInner(doorA, DIRECTION.Left);
		this.doorInnerB = new DoorInner(doorB, DIRECTION.Right);
	}
	public populateFixedWall() {
		const material = this.hypercubeParametric.configurator.materials.wallMaterial;

		const widthScaleDoor = this.params.width - this.params.epsilon - this.params.thickness * 2;
		const lengthScaleDoor = this.params.length - this.params.epsilon - this.params.thickness * 2;
		const yScale = this.params.height - this.params.epsilon - this.params.thickness * 2;
		const zScale = this.wallThickness;

		const xOff = this.params.width * 0.5 - this.params.thickness * 0.5;
		const yOff = this.params.groundY + this.params.height * 0.5;
		const zOff = this.params.length * 0.5 - this.params.thickness * 0.5;

		const config = [
			// { name: 'wall-front', scale: { x: xScale, y: yScale, z: zScale }, pos: { x: 0, y: 0, z: zOff }, rotation: { x: 0, y: 0, z: 0 } },
			{ name: 'wall-left', scale: { x: lengthScaleDoor, y: yScale, z: zScale }, pos: { x: -xOff, y: yOff, z: 0 }, rotation: { x: 0, y: -Math.PI * 0.5, z: 0 } },
			{ name: 'wall-back', scale: { x: widthScaleDoor, y: yScale, z: zScale }, pos: { x: 0, y: yOff, z: -zOff }, rotation: { x: 0, y: 0, z: 0 } },
			{ name: 'wall-right', scale: { x: lengthScaleDoor, y: yScale, z: zScale }, pos: { x: xOff, y: yOff, z: 0 }, rotation: { x: 0, y: Math.PI * 0.5, z: 0 } },
		];

		for (let i = 0; i < config.length; ++i) {
			const mesh = new THREE.Mesh(this.geometry, material);
			mesh.name = config[i].name;
			mesh.scale.set(config[i].scale.x, config[i].scale.y, config[i].scale.z);
			mesh.rotation.set(config[i].rotation.x, config[i].rotation.y, config[i].rotation.z);
			mesh.position.set(config[i].pos.x, config[i].pos.y, config[i].pos.z);
			mesh.castShadow = mesh.receiveShadow = true;
			this.mesh.push(mesh);
			this.hypercubeParametric.configurator.sceneWrapper.scene.add(mesh);
		}
	}
	public toggleSlidingDoorByID(name: string = ''): void {
		this.openDoorSliding();
	}
	public openDoorSliding(value: boolean | undefined = undefined) {
		this.doorInnerA.onOpen(value);
		this.doorInnerB.onOpen(value);
	}
	public syncSizes(): void {
		this.rebuild();
	}
	public rebuild(): void {
		this.cleanup();
		this.init();
	}
	private cleanup(): void {
		this.mesh.forEach((obj) => {
			this.hypercubeParametric.configurator.sceneWrapper.scene.remove(obj);
		});
		this.mesh = [];
	}
	public update() {
		if (this.doorInnerA.update() && this.doorInnerB.update()) {
			// if (this.doorInnerA.hasAnimation && this.doorInnerB.hasAnimation) {
			return true;
		}
		// this.doorInnerA.update() && this.doorInnerB.update();
		return false;
	}
}

export class DoorInner {
	public mesh: THREE.Mesh;
	public open = false;
	private direction: DIRECTION;
	private closedX = 0;
	private openX = 0;
	private targetX = 0;
	private speed = 0.15;

	public hasAnimation: boolean = false;

	constructor(mesh: THREE.Mesh, direction: DIRECTION) {
		this.mesh = mesh;
		this.direction = direction;

		this.closedX = mesh.position.x;

		const offset = 5.5;
		this.openX = direction === DIRECTION.Left ? this.closedX - offset : this.closedX + offset;

		this.targetX = this.closedX;
	}
	public update() {
		if (Math.abs(this.targetX - this.mesh.position.x) < 0.05) {
			this.mesh.position.x = this.targetX + 0.02;
			this.hasAnimation = false;
			return this.hasAnimation;
		}

		this.mesh.position.x += (this.targetX - this.mesh.position.x) * this.speed; // * this.hypercube.core.threeCore.rendererWrapper.deltaTime;
		this.hasAnimation = true;
		return this.hasAnimation;
	}
	public set visible(v: boolean) {
		this.mesh.children.forEach((mesh) => {
			mesh.visible = v;
		});
	}
	public onOpen(value: boolean | undefined = undefined) {
		if (value === undefined) {
			this.open = !this.open;
		} else {
			this.open = value;
		}
		this.targetX = this.open ? this.openX : this.closedX;
		this.hasAnimation = true;
	}
}
