import * as THREE from 'three';

import { HypercubeParametric } from '..';
import { getSubtractionMesh } from '../../../../../utils/ThreeUtils';

import { Parameters } from '../Parameters/Parameters';

export class ExoSkeletonMeshes {
	public hypercubeParametric: HypercubeParametric;

	public columns: THREE.Mesh[] = [];
	public bars: THREE.Mesh[] = [];
	public corners: THREE.Mesh[] = [];
	public cameras: THREE.Mesh[] = [];

	public meshes: THREE.Mesh[] = [];

	public geometry = new THREE.BoxGeometry(1, 1, 1);
	public material: THREE.Material;

	private params: Parameters;
	private _pre_thickness = 0;
	private _pre_radius = 0;

	constructor(hypercubeParametric: HypercubeParametric) {
		this.hypercubeParametric = hypercubeParametric;
		this.params = this.hypercubeParametric.params;

		this.geometry = new THREE.BoxGeometry(1, 1, 1);
		this.material = this.hypercubeParametric.configurator.materials.skeletonMaterial;
		const thickness = this.params.thickness;

		const geometryColumn = new THREE.BoxGeometry(1, 1, 1);
		const index = geometryColumn.index.array;
		const newIndices = [];
		for (let i = 0; i < index.length; i += 3) {
			const faceIndex = i / 3;
			if (faceIndex !== 4 && faceIndex !== 5) {
				newIndices.push(index[i], index[i + 1], index[i + 2]);
			}
		}
		geometryColumn.setIndex(newIndices);

		// C0 -- C1
		// |     |
		// C3 -- C2

		for (let i = 0; i < 4; ++i) {
			const mesh = new THREE.Mesh(geometryColumn, this.material);
			mesh.name = 'col-' + i;
			mesh.castShadow = true;
			mesh.receiveShadow = true;
			mesh.scale.set(thickness, thickness, thickness);
			this.columns.push(mesh);
			this.hypercubeParametric.configurator.sceneWrapper.scene.add(mesh);

			this.meshes.push(mesh);
		}

		for (let i = 0; i < 8; ++i) {
			const mesh = new THREE.Mesh(this.geometry, this.material);
			mesh.name = 'bar-' + i;
			mesh.castShadow = true;
			mesh.receiveShadow = true;
			mesh.scale.set(thickness, thickness, thickness);
			this.bars.push(mesh);
			this.hypercubeParametric.configurator.sceneWrapper.scene.add(mesh);

			this.meshes.push(mesh);
		}

		this.syncSizes();
	}
	public syncSizes() {
		// const t0 = performance.now();
		this.updateThickness(this.params.thickness);
		this.updateWidth(this.params.width);
		this.updateHeight(this.params.height);
		this.updateLength(this.params.length);
		this.updateCorners();
		// const t1 = performance.now();
		// console.log(`took ${t1 - t0} milliseconds.`);
	}
	private updateCorners() {
		const thickness = this.params.thickness;
		const radius = this.params.radiusCamera;

		if (this._pre_thickness === thickness && this._pre_radius === radius) {
			this.updateCornersPosition();
			return;
		}

		this.corners.forEach((mesh: THREE.Mesh) => this.hypercubeParametric.configurator.sceneWrapper.scene.remove(mesh));
		this.corners = [];

		const geoClone = this.geometry.clone();
		geoClone.scale(thickness, thickness, thickness);

		const geoCameraSphereA = new THREE.SphereGeometry(radius, 32, 32);
		geoCameraSphereA.scale(0.75, 1, 1);
		geoCameraSphereA.translate(-thickness * 0.5, 0, 0);

		const geoCameraSphereB = new THREE.SphereGeometry(radius, 32, 32);
		geoCameraSphereB.scale(1, 1, 0.75);
		geoCameraSphereB.translate(0, 0, -thickness * 0.5);

		let meshA = getSubtractionMesh(geoClone, geoCameraSphereA, this.material);
		let meshB = getSubtractionMesh(meshA.geometry.clone(), geoCameraSphereB, this.material);

		const geoCameraSphereAClass = new THREE.SphereGeometry(radius, 32, 32);
		geoCameraSphereAClass.scale(0.05, 1, 1);
		geoCameraSphereAClass.translate(-thickness * 0.48, 0, 0);

		const geoCameraSphereBClass = new THREE.SphereGeometry(radius, 32, 32);
		geoCameraSphereBClass.scale(1, 1, 0.05);
		geoCameraSphereBClass.translate(0, 0, -thickness * 0.48);

		for (let i = 0; i < 4; ++i) {
			const meshClone = meshB.clone();
			meshClone.geometry = meshB.geometry.clone();
			meshClone.name = 'corner-' + i;

			const angle = i * Math.PI * -0.5;
			meshClone.rotation.y = angle;

			const cameraA = new THREE.Mesh(geoCameraSphereAClass, this.hypercubeParametric.configurator.materials.glassMaterial);
			meshClone.add(cameraA);

			const cameraB = new THREE.Mesh(geoCameraSphereBClass, this.hypercubeParametric.configurator.materials.glassMaterial);
			meshClone.add(cameraB);

			this.corners.push(meshClone);
			this.hypercubeParametric.configurator.sceneWrapper.scene.add(meshClone);
		}

		// console.log('========', this.hypercubeSkin.configurator.sceneWrapper.scene.children);
		this.updateCornersPosition();

		this._pre_thickness = thickness;
		this._pre_radius = radius;
	}
	private updateCornersPosition() {
		const thicknessHalf = this.params.thickness * 0.5;
		this.corners[0].position.x = -this.params.width * 0.5 + thicknessHalf;
		this.corners[0].position.z = -this.params.length * 0.5 + thicknessHalf;
		this.corners[0].position.y = this.hypercubeParametric.configurator.sceneWrapper.groundY - thicknessHalf + this.params.height + this.params.epsilon;

		this.corners[1].position.x = this.params.width * 0.5 - thicknessHalf;
		this.corners[1].position.z = -this.params.length * 0.5 + thicknessHalf;
		this.corners[1].position.y = this.hypercubeParametric.configurator.sceneWrapper.groundY - thicknessHalf + this.params.height + this.params.epsilon;

		this.corners[2].position.x = this.params.width * 0.5 - thicknessHalf;
		this.corners[2].position.z = this.params.length * 0.5 - thicknessHalf;
		this.corners[2].position.y = this.hypercubeParametric.configurator.sceneWrapper.groundY - thicknessHalf + this.params.height + this.params.epsilon;

		this.corners[3].position.x = -this.params.width * 0.5 + thicknessHalf;
		this.corners[3].position.z = this.params.length * 0.5 - thicknessHalf;
		this.corners[3].position.y = this.hypercubeParametric.configurator.sceneWrapper.groundY - thicknessHalf + this.params.height + this.params.epsilon;
	}

	private updateWidth(value: number) {
		this.params.width = value;

		const thicknessHalf = this.params.thickness * 0.5;

		this.columns[0].position.x = -value * 0.5 + thicknessHalf;
		this.columns[1].position.x = value * 0.5 - thicknessHalf;
		this.columns[2].position.x = value * 0.5 - thicknessHalf;
		this.columns[3].position.x = -value * 0.5 + thicknessHalf;

		// bar left bottom
		this.bars[4].position.x = -value * 0.5 + thicknessHalf;
		this.bars[4].position.y = this.hypercubeParametric.configurator.sceneWrapper.groundY + thicknessHalf;

		// bar left up
		this.bars[5].position.x = -value * 0.5 + thicknessHalf;

		// bar right bottom
		this.bars[6].position.x = value * 0.5 - thicknessHalf;
		this.bars[6].position.y = this.hypercubeParametric.configurator.sceneWrapper.groundY + thicknessHalf;

		// bar right up
		this.bars[7].position.x = value * 0.5 - thicknessHalf;
	}

	private updateLength(value: number) {
		this.params.length = value;
		const thicknessHalf = this.params.thickness * 0.5;

		this.columns[0].position.z = -value * 0.5 + thicknessHalf;
		this.columns[1].position.z = -value * 0.5 + thicknessHalf;
		this.columns[2].position.z = value * 0.5 - thicknessHalf;
		this.columns[3].position.z = value * 0.5 - thicknessHalf;

		///////////////////////
		// bar up bottom
		this.bars[0].position.z = -value * 0.5 + thicknessHalf;

		// bar up top
		this.bars[1].position.z = -value * 0.5 + thicknessHalf;

		// bar down bottom
		this.bars[2].position.z = value * 0.5 - thicknessHalf;

		// bar down top
		this.bars[3].position.z = value * 0.5 - thicknessHalf;
	}
	private updateHeight(value: number) {
		this.params.height = value;
		const thicknessHalf = this.params.thickness * 0.5;
		const thickness = this.params.thickness;

		this.columns[0].scale.y = value - thickness;
		this.columns[1].scale.y = value - thickness;
		this.columns[2].scale.y = value - thickness;
		this.columns[3].scale.y = value - thickness;

		this.columns[0].position.y = value * 0.5 + this.params.groundY - thicknessHalf + this.params.epsilon;
		this.columns[1].position.y = value * 0.5 + this.params.groundY - thicknessHalf + this.params.epsilon;
		this.columns[2].position.y = value * 0.5 + this.params.groundY - thicknessHalf + this.params.epsilon;
		this.columns[3].position.y = value * 0.5 + this.params.groundY - thicknessHalf + this.params.epsilon;

		// bar up top
		this.bars[0].position.y = this.hypercubeParametric.configurator.sceneWrapper.groundY + thicknessHalf;
		this.bars[1].position.y = this.hypercubeParametric.configurator.sceneWrapper.groundY - thicknessHalf + this.params.height + this.params.epsilon;
		this.bars[2].position.y = this.hypercubeParametric.configurator.sceneWrapper.groundY + thicknessHalf;
		this.bars[3].position.y = this.hypercubeParametric.configurator.sceneWrapper.groundY - thicknessHalf + this.params.height + this.params.epsilon;
		this.bars[5].position.y = this.hypercubeParametric.configurator.sceneWrapper.groundY - thicknessHalf + this.params.height + this.params.epsilon;
		this.bars[7].position.y = this.hypercubeParametric.configurator.sceneWrapper.groundY - thicknessHalf + this.params.height + this.params.epsilon;
	}

	private updateThickness(value: number) {
		this.params.thickness = value;
		const widthHalfSkeleton = this.params.thickness * 0.5;

		this.columns[0].scale.x = value;
		this.columns[0].scale.z = value;

		this.columns[1].scale.x = value;
		this.columns[1].scale.z = value;

		this.columns[2].scale.x = value;
		this.columns[2].scale.z = value;

		this.columns[3].scale.x = value;
		this.columns[3].scale.z = value;

		this.bars[0].scale.x = this.params.width - widthHalfSkeleton * 4 - this.params.epsilon;
		this.bars[0].scale.y = value;
		this.bars[0].scale.z = value;

		this.bars[1].scale.x = this.params.width - widthHalfSkeleton * 4 - this.params.epsilon;
		this.bars[1].scale.y = value;
		this.bars[1].scale.z = value;

		this.bars[2].scale.x = this.params.width - widthHalfSkeleton * 4 - this.params.epsilon;
		this.bars[2].scale.y = value;
		this.bars[2].scale.z = value;

		this.bars[3].scale.x = this.params.width - widthHalfSkeleton * 4 - this.params.epsilon;
		this.bars[3].scale.y = value;
		this.bars[3].scale.z = value;

		///// bars
		this.bars[4].scale.x = value;
		this.bars[4].scale.y = value;
		this.bars[4].scale.z = this.params.length - widthHalfSkeleton * 4 - this.params.epsilon;

		this.bars[5].scale.x = value;
		this.bars[5].scale.y = value;
		this.bars[5].scale.z = this.params.length - widthHalfSkeleton * 4 - this.params.epsilon;

		this.bars[6].scale.x = value;
		this.bars[6].scale.y = value;
		this.bars[6].scale.z = this.params.length - widthHalfSkeleton * 4 - this.params.epsilon;

		this.bars[7].scale.x = value;
		this.bars[7].scale.y = value;
		this.bars[7].scale.z = this.params.length - widthHalfSkeleton * 4 - this.params.epsilon;
	}
}
