import { Configurator } from '..';

export class XrayViewController {
	public configurator: Configurator;
	public isActivated: boolean = false;
	constructor(configurator: Configurator) {
		this.configurator = configurator;
	}
	public toggleMode(value: boolean) {
		this.isActivated = value;
		this.update();
	}
	public update() {
		if (this.configurator.hypercubeParametric.exoSkeletonMeshes) {
			this.configurator.hypercubeParametric.exoSkeletonMeshes.columns.forEach((obj: THREE.Mesh) => {
				obj.material.transparent = this.isActivated;
				obj.material.depthWrite = !this.isActivated;
				obj.material.opacity = this.isActivated ? 0.2 : 1.0;
				obj.material.needsUpdate = true;

				obj.castShadow = !this.isActivated;
				obj.receiveShadow = !this.isActivated;
			});

			this.configurator.hypercubeParametric.exoSkeletonMeshes.bars.forEach((obj: THREE.Mesh) => {
				obj.material.transparent = this.isActivated;
				obj.material.depthWrite = !this.isActivated;
				obj.material.opacity = this.isActivated ? 0.2 : 1.0;
				obj.material.needsUpdate = true;

				obj.castShadow = !this.isActivated;
				obj.receiveShadow = !this.isActivated;
			});
		}

		if (this.configurator.hypercubeParametric.rollingDoors) {
			this.configurator.hypercubeParametric.rollingDoors.mesh.forEach((obj: THREE.Mesh) => {
				obj.material.transparent = this.isActivated;
				obj.material.depthWrite = !this.isActivated;
				obj.material.opacity = this.isActivated ? 0.1 : 1.0;
				obj.material.needsUpdate = true;

				obj.castShadow = !this.isActivated;
				obj.receiveShadow = !this.isActivated;
			});
		}

		if (this.configurator.hypercubeParametric.wall) {
			this.configurator.hypercubeParametric.wall.mesh.forEach((obj: THREE.Mesh) => {
				obj.material.transparent = this.isActivated;
				obj.material.depthWrite = !this.isActivated;
				obj.material.opacity = this.isActivated ? 0.1 : 1.0;
				obj.material.needsUpdate = true;

				obj.castShadow = !this.isActivated;
				obj.receiveShadow = !this.isActivated;
			});
		}

		// if (this.exoSkeletonMesh) {
		// 	this.exoSkeletonMesh.resultMesh.material.transparent = value;
		// 	this.exoSkeletonMesh.resultMesh.material.depthWrite = !value;
		// 	this.exoSkeletonMesh.resultMesh.material.opacity = value ? 0.2 : 1.0;
		// 	this.exoSkeletonMesh.resultMesh.material.needsUpdate = true;

		// 	this.exoSkeletonMesh.resultMesh.castShadow = !value;
		// 	this.exoSkeletonMesh.resultMesh.receiveShadow = !value;
		// }
	}
}
