import * as THREE from 'three';
import { Configurator } from '..';

import { ExoSkeletonMeshes } from './MeshParts/ExoSkeletonMeshes';
import { RollingDoor } from './MeshParts/RollingDoor';
import { FloorGrids } from './MeshParts/FloorGrids';
import { Wall } from './MeshParts/Wall';
// import { RollingDoor } from './MeshParts/RollingDoor';
// import { ExoSkeletonMesh } from './Parts/ExoSkeletonMesh';
import { Parameters } from './Parameters/Parameters';
import { exportObjects } from '../../../../utils/ThreeUtils';

export class HypercubeParametric {
	public configurator: Configurator;

	public exoSkeletonMeshes: ExoSkeletonMeshes;
	// public exoSkeletonMesh: ExoSkeletonMesh;
	public rollingDoors: RollingDoor;
	public floorGrids: FloorGrids;
	public wall: Wall;

	public params: Parameters;

	constructor(configurator: Configurator) {
		this.configurator = configurator;
		this.params = new Parameters();
		this.params.groundY = this.configurator.sceneWrapper.groundY;
		this.init();
	}
	public init() {
		this.exoSkeletonMeshes = new ExoSkeletonMeshes(this);
		this.rollingDoors = new RollingDoor(this);
		this.floorGrids = new FloorGrids(this);
		this.wall = new Wall(this);

		this.setWidth(this.params.width);
		this.setLength(this.params.length);

		let t0 = performance.now();
		// this.exoSkeletonMesh = new ExoSkeletonMesh(this);
		let t1 = performance.now();
		// console.log(`took ${t1 - t0} milliseconds.`);
	}
	public runOptimization() {
		return this.params.runOptimization();
	}
	public getParameter() {
		exportObjects(this.configurator.sceneWrapper.scene);

		const { groundY, ...rest } = this.params;
		return {
			...rest,
			date: new Date().toISOString(),
			volumeApproximation: this.params.getVolumeApproximate(),
		};
	}
	public setCameraSize(value: number) {
		this.params.setCameraSize(value);
		this.syncSizes();
	}
	public setThickness(value: number) {
		this.params.setThickness(value);
		this.syncSizes();
	}
	public setLength(value: number) {
		this.params.length = value;
		this.syncSizes();
	}
	public setHeight(value: number) {
		this.params.height = value;
		this.syncSizes();
	}
	public setWidth(value: number) {
		this.params.width = value;
		this.syncSizes();
	}
	public setHeightRollingPanel(value: number) {
		this.params.setHeightRollingPanel(value);
		this.rollingDoors.rebuild();
	}
	public setGapRollingPanel(value: number) {
		this.params.setGapRollingPanel(value);
		this.rollingDoors.rebuild();
	}
	public setSizeGridFloor(value: number) {
		this.floorGrids.scale = value;
		this.floorGrids.rebuild();
	}
	public setSize(width: number, height: number, length: number) {
		this.params.width = width;
		this.params.length = length;
		this.params.height = height;
		this.syncSizes();
	}
	public syncSizes() {
		this.exoSkeletonMeshes?.syncSizes();
		this.rollingDoors.syncSizes();
		this.floorGrids.syncSizes();
		this.wall.syncSizes();
	}
	public update() {
		// if (this.wall.update() || this.rollingDoors.update()) return true;\
		const hasAnimation = [this.rollingDoors, this.wall].some((obj) => obj.update());
		// console.log(hasAnimation);
		return hasAnimation;
	}
}
